export function findTimeSeriesProfilesById(id: string): TimeSeriesProfileRecord | undefined {
  return TIME_SERIES_PROFILES_DATABASE.find(item => item.id === id);
}

export function getAllTimeSeriesProfilesRecords(): TimeSeriesProfileRecord[] {
  return TIME_SERIES_PROFILES_DATABASE;
}

export function filterTimeSeriesProfilesByPredicate(predicate: (item: TimeSeriesProfileRecord) => boolean): TimeSeriesProfileRecord[] {
  return TIME_SERIES_PROFILES_DATABASE.filter(predicate);
}

export function countTimeSeriesProfilesRecords(): number {
  return TIME_SERIES_PROFILES_DATABASE.length;
}
